import json
from pathlib import Path

for stage in ['backend','web','mobile']:
    print(f'\n========== {stage} JSONL high-level ==========')
    with open(f'logs/{stage}.jsonl') as f:
        for i,line in enumerate(f,1):
            ev=json.loads(line)
            t=ev.get('tipo')
            if t in ('inicio','fin','paso_inicio','paso_fin','snapshot','corte','paso_omitido'):
                keys_of_interest = {k:ev.get(k) for k in ['tipo','orden','rol','paso','etapa','ts','ruta','mensaje','motivo','desde_paso'] if k in ev or k=='tipo'}
                # also nested
                extra = {}
                for k,v in ev.items():
                    if k not in ('tipo','ts','celda','harness','cli','version_cli','modelo','effort','rag','rag_config','repo_satelite','prompt_sistema','prompt_etapa','secuencia','evento') and k not in keys_of_interest:
                        if isinstance(v,(str,int,float,bool)) or v is None:
                            extra[k]=v
                        elif isinstance(v,dict):
                            extra[k]={kk:vv for kk,vv in v.items() if isinstance(vv,(str,int,float,bool)) or vv is None}
                        elif isinstance(v,list) and v and not isinstance(v[0], dict):
                            extra[k]=v
                print(f'L{i}: {json.dumps({**keys_of_interest, **extra}, ensure_ascii=False)[:500]}')
PY

