      network: assigned.network,
      chainId: assigned.chainId,
    };
    if (assetValues[0] === "USDC") response.tokenAddress = config.usdcTokenAddress;
    return reply.code(200).send(response);
  });

  return { app, db, auth, wallet };
}

function parseRegisterBody(body: unknown): { email: string; password: string } {
  if (!isRecord(body)) throw validationIssue("body", "Debe ser un objeto JSON");
  const keys = Object.keys(body);
  const unknown = keys.find((key) => key !== "email" && key !== "password");
