import type { SessionStore } from "./sessionStore";

/** Owns the in-memory token and serializes every local session teardown. */
export class SessionManager {
  private token: string | null = null;
  private clearing: Promise<void> | null = null;
  private clearRequested = false;
  private ended = false;
  private establishing = false;

  constructor(
    private readonly store: SessionStore,
    private readonly onCleared: () => void,
  ) {}

  currentToken(): string | null {
    return this.token;
  }

  async restore(): Promise<{ token: string | null; readFailed: boolean }> {
    if (this.ended) {
      await this.retryPendingClear();
      return { token: null, readFailed: false };
    }
    try {
      const token = await this.store.readToken();
      this.token = token;
      return { token, readFailed: false };
    } catch {
      this.token = null;
      return { token: null, readFailed: true };
    }
  }

  async establish(token: string): Promise<void> {
    this.establishing = true;
    try {
      if (this.clearing !== null) await this.clearing;
      if (this.clearRequested) await this.clearSingleton();
      await this.store.saveToken(token);
      this.token = token;
      this.clearRequested = false;
      this.ended = false;
      this.clearing = null;
    } finally {
      this.establishing = false;
    }
  }

  clearSingleton(): Promise<void> {
    if (this.clearing !== null) return this.clearing;
    if (!this.ended) {
      this.ended = true;
      this.token = null;
      this.clearRequested = true;
      this.onCleared();
    }
    if (!this.clearRequested) return Promise.resolve();
    this.clearing = (async () => {
      try {
        await this.store.clearToken();
        this.clearRequested = false;
      } catch {
        // Keep the deletion pending for a safe retry on the next foreground event.
      } finally {
        this.clearing = null;
      }
    })();
    return this.clearing;
  }

  retryPendingClear(): Promise<void> {
    if (this.establishing || !this.clearRequested) return Promise.resolve();
    return this.clearSingleton();
  }
}

