import { websocketUrl } from "./config";

export type ConnectionState = "connecting" | "live" | "reconnecting" | "disconnected";

interface PrivateSocketOptions {
  baseUrl: string;
  token: string;
  onUnauthenticated: () => void;
  onStateChange?: (state: ConnectionState) => void;
  socketFactory?: (url: string) => WebSocket;
  random?: () => number;
  schedule?: (callback: () => void, milliseconds: number) => ReturnType<typeof setTimeout>;
  cancelSchedule?: (timer: ReturnType<typeof setTimeout>) => void;
}

function hasUnauthenticatedError(data: unknown): boolean {
  if (typeof data !== "string") return false;
  try {
    const message: unknown = JSON.parse(data);
    return (
      typeof message === "object" &&
      message !== null &&
      "error" in message &&
      typeof message.error === "object" &&
      message.error !== null &&
      "code" in message.error &&
      message.error.code === "UNAUTHENTICATED"
    );
  } catch {
    return false;
  }
}

export class PrivateSocket {
  private socket: WebSocket | null = null;
  private retryTimer: ReturnType<typeof setTimeout> | null = null;
  private attempt = 0;
  private active = false;
  private authenticationFailed = false;
  private readonly socketFactory: (url: string) => WebSocket;
  private readonly random: () => number;
  private readonly schedule: NonNullable<PrivateSocketOptions["schedule"]>;
  private readonly cancelSchedule: NonNullable<PrivateSocketOptions["cancelSchedule"]>;

  constructor(private readonly options: PrivateSocketOptions) {
    this.socketFactory = options.socketFactory ?? ((url) => new WebSocket(url));
    this.random = options.random ?? Math.random;
    this.schedule = options.schedule ?? setTimeout;
    this.cancelSchedule = options.cancelSchedule ?? clearTimeout;
  }

  start(): void {
    if (this.active) return;
    this.active = true;
    this.attempt = 0;
    this.connect(false);
  }

  stop(): void {
    this.active = false;
    if (this.retryTimer !== null) {
      this.cancelSchedule(this.retryTimer);
      this.retryTimer = null;
    }
    const socket = this.socket;
    this.socket = null;
    if (socket && socket.readyState < 2) socket.close(1000, "App in background");
    this.options.onStateChange?.("disconnected");
  }

  private connect(retry: boolean): void {
    if (!this.active) return;
    this.options.onStateChange?.(retry ? "reconnecting" : "connecting");
    const socket = this.socketFactory(websocketUrl(this.options.baseUrl));
    this.socket = socket;
    this.authenticationFailed = false;

    socket.onopen = () => {
      if (socket !== this.socket || !this.active) return;
      socket.send(JSON.stringify({ type: "auth", token: this.options.token }));

