node --input-type=module <<'NODE'
class SessionManager {
  token = null;
  clearing = null;
  clearRequested = false;
  ended = false;
  establishing = false;
  constructor(store, onCleared) {
    this.store = store;
    this.onCleared = onCleared;
  }
  currentToken() { return this.token; }
  async establish(token) {
    this.establishing = true;
    try {
      if (this.clearing !== null) await this.clearing;
      if (this.clearRequested) await this.clearSingleton();
      await this.store.saveToken(token);
      this.token = token;
      this.clearRequested = false;
      this.ended = false;
      this.clearing = null;
    } finally {
      this.establishing = false;
    }
  }
  clearSingleton() {
    if (this.clearing !== null) return this.clearing;
    if (!this.ended) {
      this.ended = true;
      this.token = null;
      this.clearRequested = true;
      this.onCleared();
    }
    if (!this.clearRequested) return Promise.resolve();
    this.clearing = (async () => {
      try {
        await this.store.clearToken();
        this.clearRequested = false;
      } catch {
      } finally {
        this.clearing = null;
      }
    })();
    return this.clearing;
  }
}

let stored = "old";
let releaseSave;
let releaseDelete;
const saveGate = new Promise(r => releaseSave = r);
const deleteGate = new Promise(r => releaseDelete = r);
const store = {
  readToken: async () => stored,
  saveToken: async (token) => { await saveGate; stored = token; },
  clearToken: async () => { await deleteGate; stored = null; },
};
const events=[];
const manager = new SessionManager(store, () => events.push("cleared"));
const est = manager.establish("B");
// start late clear while saveToken pending
await Promise.resolve();
const clr = manager.clearSingleton();
releaseSave();
await Promise.resolve();
releaseDelete();
await Promise.all([est, clr]);
console.log(JSON.stringify({ stored, memory: manager.currentToken(), events }));
